# Cost-aware read path: coalesce + stale-while-revalidate + jittered TTL
# Trade-off: bounded staleness for 10-100x fewer origin reads.
import time, random, threading

cache = {}
locks = {}
HOT_TTL = 60          # hot keys: short TTL, high hit rate
COLD_TTL = 600        # cold keys: longer TTL, fewer origin hits
STALE_WINDOW = 30     # serve stale while refreshing in background

def get(key, loader):
    now = time.time()
    entry = cache.get(key)
    if entry and now < entry['exp']:
        return entry['val']
    if entry and now < entry['exp'] + STALE_WINDOW:
        # Amortize origin cost: only one thread refreshes.
        if locks.setdefault(key, threading.Lock()).acquire(blocking=False):
            try:
                threading.Thread(target=refresh, args=(key, loader)).start()
            finally:
                locks[key].release()
        return entry['val']  # stale but cheap
    val = loader(key)  # cache miss: pay full cost once
    ttl = HOT_TTL if is_hot(key) else COLD_TTL
    ttl += random.uniform(0, ttl * 0.2)  # jitter prevents synchronized expiry
    cache[key] = {'val': val, 'exp': now + ttl}
    return val

def refresh(key, loader):
    try:
        val = loader(key)
        cache[key] = {'val': val, 'exp': time.time() + HOT_TTL}
    except Exception:
